using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using Newtonsoft.Json;
public static class PropRepairImport{
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/";static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_PropRepair/"));
 static Material Mat(string n){var m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+n+".mat");if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,P+"Materials/"+n+".mat");}return m;}
 public static object Run(){var logs=new List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(t+": "+m);};Application.logMessageReceived+=cb;try{
 var mats=new Dictionary<string,Material>();foreach(var k in new[]{"SpecimenA","SpecimenB","Reagent","Pouch"}){string n="PR_Label_"+k,tp=P+"Textures/"+n+".png";AssetDatabase.ImportAsset(tp,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(tp);ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.wrapMode=TextureWrapMode.Clamp;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=4;ti.maxTextureSize=1024;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var m=Mat(n);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tp));m.SetColor("_BaseColor",Color.white);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",.26f);m.SetFloat("_Cull",0);mats[n]=m;}
 var glass=Mat("PR_VialGlass");glass.SetColor("_BaseColor",new Color(.64f,.78f,.79f,.20f));glass.SetFloat("_Surface",1);glass.SetFloat("_Blend",0);glass.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);glass.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);glass.SetFloat("_ZWrite",0);glass.SetFloat("_Cull",2);glass.SetFloat("_Smoothness",.83f);glass.SetFloat("_Metallic",0);glass.SetOverrideTag("RenderType","Transparent");glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.renderQueue=3000;glass.SetShaderPassEnabled("ShadowCaster",false);mats[glass.name]=glass;
 var polymer=Mat("PR_Polymer");polymer.SetColor("_BaseColor",new Color(.78f,.84f,.84f));polymer.SetFloat("_Smoothness",.38f);polymer.SetFloat("_Metallic",0);mats[polymer.name]=polymer;
 var liquid=Mat("PR_SampleFluid");liquid.SetColor("_BaseColor",new Color(.25f,.47f,.45f));liquid.SetFloat("_Smoothness",.55f);liquid.SetFloat("_Metallic",0);mats[liquid.name]=liquid;
 foreach(var m in mats.Values){EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}
 int models=0;foreach(string f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5"),"*.fbx").Where(f=>Path.GetFileName(f).StartsWith("CP_")||Path.GetFileName(f).StartsWith("ID_"))){string p=P+Path.GetFileName(f);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var im=(ModelImporter)AssetImporter.GetAtPath(p);foreach(var kv in mats)im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);im.SaveAndReimport();models++;}
 var result=new{models,newTextures=4,newMaterials=mats.Count,logs};File.WriteAllText(H+"import.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }finally{Application.logMessageReceived-=cb;}}
}
